<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{ServiceRequest,ServiceRequestEvent,User}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ServiceRequestController extends Controller {public function index(Request $r){$requests=ServiceRequest::with(['booking.property','user','assignee'])->latest()->paginate(10)->withQueryString();return view('admin.service-requests.index',compact('requests'));} public function show(ServiceRequest $serviceRequest){$serviceRequest->load(['booking.property','user','assignee']);$events=$serviceRequest->events()->with('actor')->latest()->paginate(10,['*'],'events_page')->withQueryString();$staff=User::query()->whereNotNull('staff_role')->where('is_active',true)->orderBy('name')->get();return view('admin.service-requests.show',compact('serviceRequest','staff','events'));} public function update(Request $r,ServiceRequest $serviceRequest){$d=$r->validate(['status'=>['required','in:submitted,acknowledged,in_progress,scheduled,completed,declined,cancelled'],'assigned_to'=>['nullable','exists:users,id'],'internal_notes'=>['nullable','string','max:5000'],'guest_reply'=>['nullable','string','max:5000']]);try{DB::transaction(function()use($r,$serviceRequest,$d){$old=$serviceRequest->status;$serviceRequest->update($d);ServiceRequestEvent::create(['service_request_id'=>$serviceRequest->id,'actor_id'=>$r->user()->id,'from_status'=>$old,'to_status'=>$d['status'],'note'=>$d['guest_reply']??$d['internal_notes']??null,'guest_visible'=>filled($d['guest_reply']??null)]);});return back()->with('success','Service request updated.');}catch(\Throwable $e){report($e);return back()->with('error','The service request could not be updated.');}}}
